with t as (select c.oid,n.nspname s,c.relname r,c.relrowsecurity rls from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in ('r','p') and n.nspname||'.'||c.relname = any(string_to_array('clinic_reception.doctor_sessions,clinic_reception.external_providers,clinic_reception.order_ext,clinic_reception.order_reports,clinic_reception.order_status_log,clinic_reception.provider_cost_list,clinic_reception.referral_rates,clinic_reception.report_notifications,clinic_reception.service_performers,clinic_reception.service_specialties,hub.audit,hub.card_access,hub.cards,legacy_dashboard.admins,legacy_dashboard.ai_request_limits,legacy_dashboard.amida_archive,legacy_dashboard.amida_settings,legacy_dashboard.app_secrets,legacy_dashboard.app_settings,legacy_dashboard.branch_studies,legacy_dashboard.branch_study_members,legacy_dashboard.clinic_schedule,legacy_dashboard.notifications,legacy_dashboard.operations_outbox,legacy_dashboard.reports,legacy_dashboard.tab_access,legacy_dashboard.usage_log,public.administrative_assistant_actions,public.administrative_assistant_audit,public.administrative_assistant_config,public.administrative_assistant_requests,public.administrative_assistant_rules,public.automation_run_tokens,public.clinic_faqs,public.clinic_hours,public.clinic_offers,public.clinic_profile,public.content_learnings,public.content_ratings,public.health_occasions,public.insurance_plan_service_rules,public.insurance_plans,public.kpi_defs,public.kpi_targets,public.patient_activation_codes,public.patient_feedback_signals,public.performance_evidence,public.performance_role_allocations,public.staff_kpi_alerts,public.staff_kpi_settings,public.staff_monthly_summaries,public.staff_reviews',',')))
select s,r,
 (select string_agg(a.attname||' '||format_type(a.atttypid,a.atttypmod)||case when a.attnotnull then ' not null' else '' end||coalesce(' default '||pg_get_expr(d.adbin,d.adrelid),''),' ;; ' order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=t.oid and a.attnum>0 and not a.attisdropped) cols,
 (select string_agg(conname||' '||pg_get_constraintdef(x.oid),' ;; ' order by conname) from pg_constraint x where x.conrelid=t.oid) cons,
 (select string_agg(pg_get_indexdef(i.indexrelid),' ;; ') from pg_index i where i.indrelid=t.oid and not i.indisprimary and not i.indisunique) idx,
 rls,
 (select string_agg(p.polname||' '||p.polcmd||' '||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(' check '||pg_get_expr(p.polwithcheck,p.polrelid),''),' ;; ') from pg_policy p where p.polrelid=t.oid) pols
from t order by 1,2;
